"""Local publication and distribution receipts pin original content; no parallel media."""
from sqlalchemy import Column,Text,Integer,String,Boolean,ForeignKey,ForeignKeyConstraint,UniqueConstraint,CheckConstraint,Index
from sqlalchemy.dialects.postgresql import UUID,JSONB

COMMUNITY_TABLES=('community_rules','community_publications','community_versions','community_events','community_reports','community_moderation','distribution_channels','distribution_requests','distribution_events','template_copy_media','template_copy_domains')
COMMUNITY_IMMUTABLE=tuple(name for name in COMMUNITY_TABLES if name!='community_publications')

def declare_community(project_table,ref,uid,stamp):
    def person(name):return Column(name,UUID(as_uuid=False),ForeignKey('access_identities.id',ondelete='RESTRICT'),nullable=False)
    rules=project_table('community_rules',Column('version',Integer,nullable=False),Column('title',Text,nullable=False),Column('body',Text,nullable=False),Column('sha256',String(64),nullable=False),person('created_by'),stamp(),UniqueConstraint('project_id','version'),CheckConstraint('version>0',name='version'))
    pubs=project_table('community_publications',person('created_by'),uid('current_version_id',nullable=True),stamp())
    versions=project_table('community_versions',*ref('community_publications','publication_id'),Column('version',Integer,nullable=False),Column('title',Text,nullable=False),Column('description',Text,nullable=False),Column('scope',Text,nullable=False),*ref('community_rules','rule_id'),*ref('media_items','media_id',nullable=True),uid('blob_id',nullable=True),Column('blob_sha256',String(64)),*ref('canvas_templates','template_id',nullable=True),Column('content_sha256',String(64),nullable=False),person('created_by'),stamp(),UniqueConstraint('project_id','publication_id','version'),UniqueConstraint('project_id','publication_id','id'),ForeignKeyConstraint(['project_id','media_id','blob_id'],['media_items.project_id','media_items.id','media_items.blob_id']),ForeignKeyConstraint(['blob_id','blob_sha256'],['media_blobs.id','media_blobs.sha256']),CheckConstraint("version>0 AND scope IN ('project','workspace') AND num_nonnulls(media_id,template_id)=1 AND (media_id IS NULL)=(blob_id IS NULL) AND (media_id IS NULL)=(blob_sha256 IS NULL)",name='content'))
    pubs.append_constraint(ForeignKeyConstraint(['project_id','id','current_version_id'],['community_versions.project_id','community_versions.publication_id','community_versions.id'],name='fk_community_current_version',use_alter=True))
    events=project_table('community_events',*ref('community_versions','version_id'),Column('sequence',Integer,nullable=False),Column('status',Text,nullable=False),Column('reason',Text,nullable=False),person('created_by'),stamp(),UniqueConstraint('project_id','version_id','sequence'),CheckConstraint("sequence>0 AND status IN ('draft','published','withdrawn','restricted')",name='status'))
    reports=project_table('community_reports',*ref('community_versions','version_id'),*ref('community_rules','rule_id'),person('reporter_id'),Column('reason',Text,nullable=False),stamp(),UniqueConstraint('project_id','id','version_id','rule_id'))
    moderation=project_table('community_moderation',*ref('community_versions','version_id'),*ref('community_rules','rule_id'),*ref('community_reports','report_id',nullable=True),*ref('community_moderation','previous_decision_id',nullable=True),Column('action',Text,nullable=False),Column('reason',Text,nullable=False),person('created_by'),stamp(),ForeignKeyConstraint(['project_id','report_id','version_id','rule_id'],['community_reports.project_id','community_reports.id','community_reports.version_id','community_reports.rule_id']),CheckConstraint("action IN ('restrict','release','dismiss')",name='action'))
    channels=project_table('distribution_channels',Column('channel_key',Text,nullable=False),Column('version',Integer,nullable=False),Column('name',Text,nullable=False),Column('adapter',Text,nullable=False),Column('endpoint',Text,nullable=False),Column('credential_env',Text,nullable=False),Column('enabled',Boolean,nullable=False),Column('sha256',String(64),nullable=False),person('created_by'),stamp(),UniqueConstraint('project_id','channel_key','version'),CheckConstraint('version>0',name='version'))
    requests=project_table('distribution_requests',*ref('community_versions','version_id'),*ref('distribution_channels','channel_id'),Column('caption',Text,nullable=False),Column('request_sha256',String(64),nullable=False),Column('request_key',Text,nullable=False,unique=True),person('created_by'),stamp())
    receipts=project_table('distribution_events',*ref('distribution_requests','request_id'),Column('sequence',Integer,nullable=False),Column('status',Text,nullable=False),Column('remote_id',Text),Column('public_url',Text),Column('error_code',Text),person('created_by'),stamp(),UniqueConstraint('project_id','request_id','sequence'),CheckConstraint("sequence>0 AND status IN ('prepared','submitting','submitted','unknown','completed','failed','cancelled')",name='status'))
    media=project_table('template_copy_media',*ref('canvas_template_copies','copy_id'),uid('source_project_id',nullable=False),uid('source_media_id',nullable=False),*ref('media_items','target_media_id'),uid('blob_id',nullable=False),Column('sha256',String(64),nullable=False),ForeignKeyConstraint(['source_project_id','source_media_id','blob_id'],['media_items.project_id','media_items.id','media_items.blob_id']),ForeignKeyConstraint(['project_id','target_media_id','blob_id'],['media_items.project_id','media_items.id','media_items.blob_id']),ForeignKeyConstraint(['blob_id','sha256'],['media_blobs.id','media_blobs.sha256']),UniqueConstraint('project_id','copy_id','source_media_id'))
    domains=project_table('template_copy_domains',*ref('canvas_template_copies','copy_id'),uid('source_project_id',nullable=False),uid('source_spatial_version_id',nullable=True),*ref('spatial_scene_versions','target_spatial_version_id',nullable=True),uid('source_tool_version_id',nullable=True),*ref('artifact_versions','target_tool_version_id',nullable=True),uid('source_edit_version_id',nullable=True),*ref('edit_revisions','target_edit_version_id',nullable=True),ForeignKeyConstraint(['source_project_id','source_spatial_version_id'],['spatial_scene_versions.project_id','spatial_scene_versions.id']),ForeignKeyConstraint(['source_project_id','source_tool_version_id'],['artifact_versions.project_id','artifact_versions.id']),ForeignKeyConstraint(['source_project_id','source_edit_version_id'],['edit_revisions.project_id','edit_revisions.id']),CheckConstraint('num_nonnulls(source_spatial_version_id,source_tool_version_id,source_edit_version_id)=1 AND (source_spatial_version_id IS NULL)=(target_spatial_version_id IS NULL) AND (source_tool_version_id IS NULL)=(target_tool_version_id IS NULL) AND (source_edit_version_id IS NULL)=(target_edit_version_id IS NULL)',name='typed_mapping'))
    result={t.name:t for t in (rules,pubs,versions,events,reports,moderation,channels,requests,receipts,media,domains)}
    for table in result.values():
        for c in table.c:
            if c.name.endswith('_id') and c.name not in {'project_id','id'}:Index('ix_'+table.name+'_'+c.name,table.c.project_id,c)
    return result
